<?php require "init.php"; $db = $database->getConnection(); $db->query("CREATE TABLE IF NOT EXISTS notification_groups (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, created_by INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); $db->query("CREATE TABLE IF NOT EXISTS group_members (group_id INT NOT NULL, osy_id INT NOT NULL, PRIMARY KEY (group_id, osy_id), FOREIGN KEY (group_id) REFERENCES notification_groups(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); echo "Success"; ?>
